local FishingRodMaker = {}
local PRODUCTS = {
    simple_wood_fishing_rod = { name = "Preprost leseni ribiška palica", woodCost = 2, ropeCost = 1, time = 2, cost = 30, food = 8, happiness = 1, description = "Preprost leseni ribiška palica za ribolov." },
    bamboo_fishing_rod = { name = "Bambusova ribiška palica", woodCost = 3, ropeCost = 1, threadCost = 1, time = 4, cost = 90, food = 15, happiness = 1, prestige = 2, description = "Bambusova ribiška palica za trgovce." },
    silver_guided_rod = { name = "Srebrnavodilna ribiška palica", woodCost = 3, silverCost = 1, ropeCost = 1, threadCost = 1, time = 7, cost = 240, food = 25, happiness = 2, prestige = 6, description = "Srebrnavodilna ribiška palica za plemiče." },
    gold_trimmed_rod = { name = "Zlatookrasna ribiška palica", woodCost = 3, goldCost = 1, silverCost = 1, ropeCost = 1, threadCost = 1, time = 11, cost = 580, food = 38, happiness = 3, prestige = 14, description = "Zlatookrasna ribiška palica za visoke plemiče." },
    jewel_reel_rod = { name = "Draguljnavaltasta ribiška palica", woodCost = 3, goldCost = 1, silverCost = 1, ropeCost = 1, threadCost = 1, jewelCost = 1, time = 15, cost = 1300, food = 52, happiness = 5, prestige = 27, description = "Ribiška palica z draguljno valto za visoko plemstvo." },
    royal_grand_fishing_rod = { name = "Kraljevski veliki ribiška palica", woodCost = 5, goldCost = 2, silverCost = 2, ropeCost = 1, threadCost = 1, jewelCost = 2, pearlCost = 2, time = 22, cost = 2900, food = 72, happiness = 12, prestige = 58, description = "Velika kraljevska ribiška palica z biseri in zlatom za kronanje." },
}
local BUILDINGS = {
    rod_workshop = { name = "Palicna delavnica", cost = { gold = 240, wood = 140, stone = 120, rope = 6, thread = 4 }, upkeep = 5, qualityBonus = 5 },
    fishing_loft = { name = "Ribiška podstrešje", cost = { gold = 880, wood = 280, stone = 240, silver = 6, thread = 6 }, upkeep = 20, qualityBonus = 18 },
    master_rod_atelier = { name = "Mojstrski palicni atelje", cost = { gold = 2500, wood = 380, stone = 520, silver = 30, gold = 6 }, upkeep = 58, qualityBonus = 30 },
    royal_fishery_palace = { name = "Kraljevska ribiška palača", cost = { gold = 10500, wood = 580, stone = 760, gold = 65, jewel = 16 }, upkeep = 210, qualityBonus = 55, prestigeBonus = 50 },
}
FishingRodMaker.woodStock = 18; FishingRodMaker.ropeStock = 10; FishingRodMaker.threadStock = 10; FishingRodMaker.silverStock = 6; FishingRodMaker.goldStock = 6; FishingRodMaker.jewelStock = 4; FishingRodMaker.pearlStock = 4
FishingRodMaker.productStock = {}; FishingRodMaker.buildings = {}; FishingRodMaker.maker = nil; FishingRodMaker.activeMaking = {}; FishingRodMaker.totalProducts = 0; FishingRodMaker.dayTimer = 0
function FishingRodMaker.init() FishingRodMaker.woodStock=18; FishingRodMaker.ropeStock=10; FishingRodMaker.threadStock=10; FishingRodMaker.silverStock=6; FishingRodMaker.goldStock=6; FishingRodMaker.jewelStock=4; FishingRodMaker.pearlStock=4; FishingRodMaker.productStock={}; FishingRodMaker.buildings={}; FishingRodMaker.maker=nil; FishingRodMaker.activeMaking={}; FishingRodMaker.totalProducts=0; FishingRodMaker.dayTimer=0; print("[FishingRodMaker] Royal Fishing Rod Maker System initialized (6 products, 4 buildings)") end
function FishingRodMaker.hireMaker(n,s) s=s or math.random(55,90); local c=500+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; FishingRodMaker.maker={name=n or ("Palicar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Palicar najet: %s (spretnost: %d)",FishingRodMaker.maker.name,s),"success") end; return true end
function FishingRodMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function FishingRodMaker.build(id) local ok,e=FishingRodMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(FishingRodMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function FishingRodMaker.getQualityBonus() local b=0; for _,bd in ipairs(FishingRodMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function FishingRodMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.woodCost and FishingRodMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.ropeCost and FishingRodMaker.ropeStock<(d.ropeCost or 0) then return false,"Premalo vrvi" end; if d.threadCost and FishingRodMaker.threadStock<(d.threadCost or 0) then return false,"Premalo niti" end; if d.silverCost and FishingRodMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and FishingRodMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and FishingRodMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and FishingRodMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #FishingRodMaker.buildings==0 then return false,"Potrebna palicna delavnica" end; if not FishingRodMaker.maker then return false,"Potreben palicar" end; return true end
function FishingRodMaker.make(pt,qty) qty=qty or 1; local ok,e=FishingRodMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.woodCost then FishingRodMaker.woodStock=FishingRodMaker.woodStock-d.woodCost*qty end; if d.ropeCost then FishingRodMaker.ropeStock=FishingRodMaker.ropeStock-d.ropeCost*qty end; if d.threadCost then FishingRodMaker.threadStock=FishingRodMaker.threadStock-d.threadCost*qty end; if d.silverCost then FishingRodMaker.silverStock=FishingRodMaker.silverStock-d.silverCost*qty end; if d.goldCost then FishingRodMaker.goldStock=FishingRodMaker.goldStock-d.goldCost*qty end; if d.jewelCost then FishingRodMaker.jewelStock=FishingRodMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then FishingRodMaker.pearlStock=FishingRodMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if FishingRodMaker.maker then t=math.max(1,t-math.floor(FishingRodMaker.maker.skill/14)) end; table.insert(FishingRodMaker.activeMaking,{id="fishingrod_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=d.food or 0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function FishingRodMaker.completeMaking(m) local q=1.0+(FishingRodMaker.getQualityBonus()/100); if FishingRodMaker.maker then q=q+(FishingRodMaker.maker.skill/140) end; q=math.min(2.5,q); FishingRodMaker.productStock[m.productType]=(FishingRodMaker.productStock[m.productType] or 0)+m.quantity; FishingRodMaker.totalProducts=FishingRodMaker.totalProducts+m.quantity; if m.food>0 and _G.state then _G.state.food=(_G.state.food or 0)+m.food end; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if FishingRodMaker.maker then FishingRodMaker.maker.itemsMade=FishingRodMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then FishingRodMaker.maker.skill=math.min(100,FishingRodMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Ribiška palica izdelana: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"fishingrod.completed",{productName=m.productName,food=m.food,prestige=m.prestige,happiness=m.happiness}) end end
function FishingRodMaker.update(dt) if not _G.state then return end; FishingRodMaker.dayTimer=FishingRodMaker.dayTimer+dt; if FishingRodMaker.dayTimer>=30 then FishingRodMaker.dayTimer=0; for i=#FishingRodMaker.activeMaking,1,-1 do local m=FishingRodMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then FishingRodMaker.completeMaking(m); table.remove(FishingRodMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(FishingRodMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if FishingRodMaker.maker then tu=tu+13 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function FishingRodMaker.getStats() return {woodStock=FishingRodMaker.woodStock,ropeStock=FishingRodMaker.ropeStock,threadStock=FishingRodMaker.threadStock,silverStock=FishingRodMaker.silverStock,goldStock=FishingRodMaker.goldStock,jewelStock=FishingRodMaker.jewelStock,pearlStock=FishingRodMaker.pearlStock,productStock=FishingRodMaker.productStock,numBuildings=#FishingRodMaker.buildings,hasMaker=FishingRodMaker.maker~=nil,makerName=FishingRodMaker.maker and FishingRodMaker.maker.name or "—",makerSkill=FishingRodMaker.maker and FishingRodMaker.maker.skill or 0,activeMaking=#FishingRodMaker.activeMaking,totalProducts=FishingRodMaker.totalProducts} end
return FishingRodMaker
